@layer hj.components {
  /* Same surface as Dialog. Customise: --hj-alert-dialog-width · --hj-alert-dialog-scrim */
  .hj-alert-dialog-backdrop {
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    min-height: 100dvh;
    background: var(--hj-scrim);
    opacity: var(--hj-alert-dialog-scrim, 0.55);
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-alert-dialog-backdrop[data-starting-style],
  .hj-alert-dialog-backdrop[data-ending-style] {
    opacity: 0;
  }
  .hj-alert-dialog-backdrop[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
  }

  .hj-alert-dialog-popup {
    --_w: var(--hj-alert-dialog-width, 380px);
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    margin: auto;
    width: min(var(--_w), calc(100vw - 32px));
    height: fit-content;
    max-height: calc(100dvh - 48px);
    overflow: auto;
    display: flex;
    flex-direction: column;
    gap: calc(8px * var(--hj-density));
    padding: calc(24px * var(--hj-density));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-radius-lg);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    transform: translateY(calc(-10px * var(--nested-dialogs, 0)))
      scale(calc(1 - 0.05 * var(--nested-dialogs, 0)));
    transition:
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-alert-dialog-popup[data-size='md'] {
    --_w: var(--hj-alert-dialog-width, 480px);
  }
  .hj-alert-dialog-popup[data-starting-style] {
    opacity: 0;
    transform: scale(0.94);
  }
  .hj-alert-dialog-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.97);
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }

  .hj-alert-dialog-glyph {
    display: grid;
    place-items: center;
    width: 40px;
    height: calc(40px * var(--hj-density-size));
    margin-bottom: calc(6px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: var(--hj-danger-soft);
    color: var(--hj-danger);
    line-height: 0;
  }
  .hj-alert-dialog-glyph > svg {
    width: 20px;
    height: 20px;
  }

  .hj-alert-dialog-title {
    margin: 0;
    font: var(--hj-type-title);
    letter-spacing: var(--hj-tracking-title);
  }
  .hj-alert-dialog-description {
    margin: 0;
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--hj-fg-dim);
  }
  .hj-alert-dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: calc(8px * var(--hj-density));
    margin-top: calc(16px * var(--hj-density));
  }
}

'use client';
import { AlertDialog as Base } from '@base-ui/react/alert-dialog';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'AlertDialog.Trigger',
  'hj-alert-dialog-trigger',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'AlertDialog.Backdrop',
  'hj-alert-dialog-backdrop',
);
export const Title: HanjiPart<typeof Base.Title> = part(
  Base.Title,
  'AlertDialog.Title',
  'hj-alert-dialog-title',
);
export const Description: HanjiPart<typeof Base.Description> = part(
  Base.Description,
  'AlertDialog.Description',
  'hj-alert-dialog-description',
);
/** Closes. Use with `render={<Button … />}` for each of the (at most two) choices. */
export const Close: HanjiPart<typeof Base.Close> = part(
  Base.Close,
  'AlertDialog.Close',
  'hj-alert-dialog-close',
);
/** Footer row: the safe choice first, the consequence last. Never more than two. */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'AlertDialog.Actions',
  'hj-alert-dialog-actions',
);
export const createHandle: typeof Base.createHandle = Base.createHandle;

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface PopupOwnProps {
  /** Width: sm 380 (hanji), md 480. */
  size?: 'sm' | 'md';
  /** danger leads with the alert glyph in a danger tint, so the consequence is never colour alone. */
  tone?: 'default' | 'danger';
}
export interface PopupProps extends PopupOwnProps, Base.Popup.Props {}

/** The surface. An alert dialog has no corner ✕ and ignores outside presses: it must be answered. */
export function Popup(props: PopupProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    size = 'sm',
    tone = 'default',
    className,
    children,
    ...rest
  } = withDefaults(config, 'AlertDialog.Popup', props);
  return (
    <Base.Popup
      {...rest}
      data-size={size}
      data-tone={tone === 'default' ? undefined : tone}
      className={cls(config, 'AlertDialog.Popup', 'hj-alert-dialog-popup', className)}
    >
      {tone === 'danger' ? (
        <span className={config.unstyled ? undefined : 'hj-alert-dialog-glyph'} aria-hidden="true">
          {config.icons.alert}
        </span>
      ) : null}
      {children}
    </Base.Popup>
  );
}

export interface ContentOwnProps {
  container?: Base.Portal.Props['container'];
  keepMounted?: boolean;
}
export interface ContentProps extends ContentOwnProps, PopupProps {}

/** Shorthand for Portal + Backdrop + Popup. */
export function Content({ container, keepMounted, ...popup }: ContentProps): React.ReactElement {
  return (
    <Portal container={container} keepMounted={keepMounted}>
      <Backdrop />
      <Popup {...popup} />
    </Portal>
  );
}

export * as AlertDialog from './alert-dialog.tsx';
export type {
  ContentOwnProps as AlertDialogContentOwnProps,
  ContentProps as AlertDialogContentProps,
  PopupOwnProps as AlertDialogPopupOwnProps,
  PopupProps as AlertDialogPopupProps,
} from './alert-dialog.tsx';
